  1	import AsyncStorage from "@react-native-async-storage/async-storage";
  2	import { KEATING_WEB_ORIGIN } from "../product-links";
  3	import { type CookieJar, mergeCookies, parseSetCookie, serializeCookies } from "./cookie-jar";
  4	import {
  5	  type CourseListItem,
  6	  type CourseSessionAccount,
  7	  type CourseViewerSnapshot,
  8	  normalizeCourseListItem,
  9	  normalizeCourseSnapshot,
 10	} from "./types";
 11	
 12	const COOKIE_STORAGE_KEY = "keating.mobile.course-cookies";
 13	
 14	/** A course request that failed with the server's own error code attached. */
 15	export class CourseApiError extends Error {
 16	  constructor(readonly status: number, message: string, readonly code: string) {
 17	    super(message);
 18	    this.name = "CourseApiError";
 19	  }
 20	
 21	  /** True when the learner is not a member, or the invite did not apply. */
 22	  get isAccessProblem(): boolean {
 23	    return this.status === 401 || this.status === 403 || this.status === 404;
 24	  }
 25	}
 26	
 27	let jar: CookieJar | null = null;
 28	
 29	async function loadJar(): Promise<CookieJar> {
 30	  if (jar) return jar;
 31	  try {
 32	    const raw = await AsyncStorage.getItem(COOKIE_STORAGE_KEY);
 33	    jar = raw ? JSON.parse(raw) as CookieJar : {};
 34	  } catch {
 35	    jar = {};
 36	  }
 37	  return jar;
 38	}
 39	
 40	async function rememberCookies(header: string | null): Promise<void> {
 41	  const incoming = parseSetCookie(header);
 42	  if (Object.keys(incoming).length === 0) return;
 43	  const next = mergeCookies(await loadJar(), incoming);
 44	  jar = next;
 45	  await AsyncStorage.setItem(COOKIE_STORAGE_KEY, JSON.stringify(next)).catch(() => undefined);
 46	}
 47	
 48	/** Drops the stored session; the next request starts a fresh course account. */
 49	export async function clearCourseSession(): Promise<void> {
 50	  jar = {};
 51	  await AsyncStorage.removeItem(COOKIE_STORAGE_KEY).catch(() => undefined);
 52	}
 53	
 54	export interface CourseRequestOptions {
 55	  signal?: AbortSignal;
 56	  fetchImpl?: typeof fetch;
 57	}
 58	
 59	async function request<T>(
 60	  path: string,
 61	  init: RequestInit,
 62	  normalize: (payload: unknown) => T,
 63	  options: CourseRequestOptions = {},
 64	): Promise<T> {
 65	  const { signal, fetchImpl = fetch } = options;
 66	  const cookie = serializeCookies(await loadJar());
 67	  const headers: Record<string, string> = {
 68	    Accept: "application/json",
 69	    ...(init.body ? { "Content-Type": "application/json" } : {}),
 70	    ...(cookie ? { Cookie: cookie } : {}),
 71	  };
 72	
 73	  let response: Response;
 74	  try {
 75	    response = await fetchImpl(`${KEATING_WEB_ORIGIN}/api/courses${path}`, { ...init, headers, signal });
 76	  } catch (error) {
 77	    if (error instanceof Error && error.name === "AbortError") throw error;
 78	    throw new CourseApiError(0, "Could not reach Keating. Check your connection.", "course_offline");
 79	  }
 80	
 81	  await rememberCookies(response.headers.get("set-cookie"));
 82	
 83	  const text = await response.text();
 84	  let payload: unknown = null;
 85	  try {
 86	    payload = text ? JSON.parse(text) : null;
 87	  } catch {
 88	    payload = null;
 89	  }
 90	
 91	  if (!response.ok) {
 92	    const body = (payload ?? {}) as Record<string, unknown>;
 93	    const data = (body.data ?? {}) as Record<string, unknown>;
 94	    const message = typeof body.statusMessage === "string" && body.statusMessage
 95	      ? body.statusMessage
 96	      : typeof body.message === "string" && body.message
 97	        ? body.message
 98	        : `The course server returned HTTP ${response.status}.`;
 99	    throw new CourseApiError(
100	      response.status,
101	      message,
102	      typeof data.code === "string" ? data.code : "course_request_failed",
103	    );
104	  }
105	
106	  return normalize(payload);
107	}
108	
109	export function fetchCourseSession(options?: CourseRequestOptions): Promise<CourseSessionAccount> {
110	  return request("/session", { method: "GET" }, (payload) => {
111	    const account = ((payload ?? {}) as Record<string, unknown>).account as Record<string, unknown> ?? {};
112	    return {
113	      id: typeof account.id === "string" ? account.id : "",
114	      displayName: typeof account.displayName === "string" ? account.displayName : "Learner",
115	      mode: account.mode === "hosted" || account.mode === "development" ? account.mode : "local",
116	    };
117	  }, options);
118	}
119	
120	export function fetchCourses(options?: CourseRequestOptions): Promise<CourseListItem[]> {
121	  return request("", { method: "GET" }, (payload) => {
122	    const courses = ((payload ?? {}) as Record<string, unknown>).courses;
123	    return Array.isArray(courses) ? courses.map(normalizeCourseListItem) : [];
124	  }, options);
125	}
126	
127	export function fetchCourse(courseId: string, options?: CourseRequestOptions): Promise<CourseViewerSnapshot> {
128	  return request(`/${encodeURIComponent(courseId)}`, { method: "GET" }, normalizeCourseSnapshot, options);
129	}
130	
131	/**
132	 * Redeems an invite code. `acceptTeacherAccess` is the learner's explicit
133	 * consent to let course teachers see their work, so it is always passed
134	 * through from a deliberate choice rather than defaulted on.
135	 */
136	export function joinCourse(
137	  inviteCode: string,
138	  acceptTeacherAccess: boolean,
139	  options?: CourseRequestOptions,
140	): Promise<CourseViewerSnapshot> {
141	  return request(
142	    `/join/${encodeURIComponent(inviteCode)}`,
143	    { method: "POST", body: JSON.stringify({ acceptTeacherAccess }) },
144	    normalizeCourseSnapshot,
145	    options,
146	  );
147	}
148	
149	/** Absolute URL for a material the app hands off to the browser. */
150	export function courseMaterialUrl(courseId: string, materialId: string): string {
151	  return `${KEATING_WEB_ORIGIN}/api/courses/${encodeURIComponent(courseId)}/materials/${encodeURIComponent(materialId)}`;
152	}

 1	/**
 2	 * A minimal cookie jar for the course API.
 3	 *
 4	 * Course auth is a server-set session cookie. React Native's networking stack
 5	 * usually persists cookies natively, but that is platform-dependent and
 6	 * invisible to tests, so the client also keeps its own jar: it records any
 7	 * `set-cookie` it can see and replays it on later requests. Belt and braces —
 8	 * whichever mechanism works, the session survives an app restart.
 9	 *
10	 * Parsing lives here, free of storage and React Native imports, so it can be
11	 * exercised directly under `bun test`.
12	 */
13	
14	export type CookieJar = Readonly<Record<string, string>>;
15	
16	/**
17	 * Pulls `name=value` pairs out of a `set-cookie` header, ignoring attributes
18	 * (`Path`, `HttpOnly`, `Max-Age`, …). React Native folds multiple cookies into
19	 * one comma-joined header, so splitting has to skip the commas inside an
20	 * `Expires=Wed, 09 Jun 2027 …` date.
21	 */
22	export function parseSetCookie(header: string | null | undefined): Record<string, string> {
23	  if (!header) return {};
24	  const jar: Record<string, string> = {};
25	  for (const chunk of splitCookieHeader(header)) {
26	    const pair = chunk.split(";", 1)[0]?.trim();
27	    if (!pair) continue;
28	    const separator = pair.indexOf("=");
29	    if (separator <= 0) continue;
30	    const name = pair.slice(0, separator).trim();
31	    const value = pair.slice(separator + 1).trim();
32	    // An empty value with an expiry in the past is a deletion; drop the name
33	    // rather than replaying a blank cookie.
34	    if (name) jar[name] = value;
35	  }
36	  return jar;
37	}
38	
39	function splitCookieHeader(header: string): string[] {
40	  const parts: string[] = [];
41	  let current = "";
42	  for (let index = 0; index < header.length; index += 1) {
43	    const character = header[index]!;
44	    if (character !== ",") {
45	      current += character;
46	      continue;
47	    }
48	    // A comma starts a new cookie only when what follows looks like `name=`
49	    // before the next `;` — otherwise it belongs to a date inside an attribute.
50	    const rest = header.slice(index + 1);
51	    if (/^\s*[^=;,\s]+=/.test(rest)) {
52	      parts.push(current);
53	      current = "";
54	    } else {
55	      current += character;
56	    }
57	  }
58	  if (current.trim()) parts.push(current);
59	  return parts;
60	}
61	
62	export function mergeCookies(jar: CookieJar, incoming: Record<string, string>): CookieJar {
63	  const next: Record<string, string> = { ...jar };
64	  for (const [name, value] of Object.entries(incoming)) {
65	    if (value === "") delete next[name];
66	    else next[name] = value;
67	  }
68	  return next;
69	}
70	
71	/** Serialises the jar into a `Cookie` request header, or `null` when empty. */
72	export function serializeCookies(jar: CookieJar): string | null {
73	  const entries = Object.entries(jar);
74	  if (entries.length === 0) return null;
75	  return entries.map(([name, value]) => `${name}=${value}`).join("; ");
76	}

  1	/**
  2	 * The slice of the course contract this app reads. The server owns the full
  3	 * schema (web/src/courses/contracts.ts); these are hand-mirrored structural
  4	 * types for the read paths the native client uses, so the app never needs zod
  5	 * on device. Anything unmodelled is simply ignored.
  6	 */
  7	
  8	export type CourseRole = "owner" | "teacher" | "student" | "peer";
  9	export type TeacherAccess = "private" | "requested" | "full";
 10	export type CourseMaterialKind = "document" | "image" | "link" | "note" | "anki";
 11	
 12	export interface CourseSessionAccount {
 13	  id: string;
 14	  displayName: string;
 15	  mode: "development" | "local" | "hosted";
 16	}
 17	
 18	export interface CourseListItem {
 19	  id: string;
 20	  title: string;
 21	  description: string;
 22	  role: CourseRole;
 23	  memberCount: number;
 24	  lessonCount: number;
 25	  completedLessons: number;
 26	  updatedAt: string;
 27	}
 28	
 29	export interface CourseMaterial {
 30	  id: string;
 31	  kind: CourseMaterialKind;
 32	  title: string;
 33	  description?: string;
 34	  url?: string;
 35	  fileName?: string;
 36	  mimeType?: string;
 37	  sizeBytes?: number;
 38	  lessonId?: string;
 39	  createdAt: string;
 40	}
 41	
 42	export interface CourseLesson {
 43	  id: string;
 44	  title: string;
 45	  summary: string;
 46	  estimatedMinutes?: number;
 47	  objectives: string[];
 48	  reading: string;
 49	  materialIds: string[];
 50	}
 51	
 52	export interface CourseModule {
 53	  id: string;
 54	  title: string;
 55	  description: string;
 56	  lessons: CourseLesson[];
 57	}
 58	
 59	export interface CourseProgress {
 60	  activeLessonId?: string;
 61	  completedLessonIds: string[];
 62	  lastActiveAt: string;
 63	}
 64	
 65	export interface CourseMember {
 66	  accountId: string;
 67	  displayName: string;
 68	  role: CourseRole;
 69	  teacherAccess: TeacherAccess;
 70	  progress: CourseProgress;
 71	}
 72	
 73	export interface Course {
 74	  id: string;
 75	  title: string;
 76	  description: string;
 77	  outcomes: string[];
 78	  updatedAt: string;
 79	  revision: number;
 80	  modules: CourseModule[];
 81	  materials: CourseMaterial[];
 82	  members: CourseMember[];
 83	}
 84	
 85	export interface CoursePermissions {
 86	  canEditCourse: boolean;
 87	  canInvite: boolean;
 88	  canReview: boolean;
 89	  canEditDeck: boolean;
 90	  canRequestTeacherAccess: boolean;
 91	}
 92	
 93	export interface CourseViewerSnapshot {
 94	  course: Course;
 95	  viewer: CourseMember;
 96	  permissions: CoursePermissions;
 97	}
 98	
 99	const ROLES = new Set<CourseRole>(["owner", "teacher", "student", "peer"]);
100	const MATERIAL_KINDS = new Set<CourseMaterialKind>(["document", "image", "link", "note", "anki"]);
101	
102	function str(value: unknown, fallback = ""): string {
103	  return typeof value === "string" ? value : fallback;
104	}
105	
106	function strArray(value: unknown): string[] {
107	  return Array.isArray(value) ? value.filter((entry): entry is string => typeof entry === "string") : [];
108	}
109	
110	function record(value: unknown): Record<string, unknown> {
111	  return typeof value === "object" && value !== null ? value as Record<string, unknown> : {};
112	}
113	
114	function role(value: unknown): CourseRole {
115	  return ROLES.has(value as CourseRole) ? value as CourseRole : "student";
116	}
117	
118	export function normalizeCourseListItem(value: unknown): CourseListItem {
119	  const item = record(value);
120	  return {
121	    id: str(item.id),
122	    title: str(item.title, "Untitled course"),
123	    description: str(item.description),
124	    role: role(item.role),
125	    memberCount: typeof item.memberCount === "number" ? item.memberCount : 0,
126	    lessonCount: typeof item.lessonCount === "number" ? item.lessonCount : 0,
127	    completedLessons: typeof item.completedLessons === "number" ? item.completedLessons : 0,
128	    updatedAt: str(item.updatedAt),
129	  };
130	}
131	
132	function normalizeMaterial(value: unknown): CourseMaterial {
133	  const material = record(value);
134	  const kind = MATERIAL_KINDS.has(material.kind as CourseMaterialKind)
135	    ? material.kind as CourseMaterialKind
136	    : "note";
137	  return {
138	    id: str(material.id),
139	    kind,
140	    title: str(material.title, "Untitled material"),
141	    description: typeof material.description === "string" ? material.description : undefined,
142	    url: typeof material.url === "string" ? material.url : undefined,
143	    fileName: typeof material.fileName === "string" ? material.fileName : undefined,
144	    mimeType: typeof material.mimeType === "string" ? material.mimeType : undefined,
145	    sizeBytes: typeof material.sizeBytes === "number" ? material.sizeBytes : undefined,
146	    lessonId: typeof material.lessonId === "string" ? material.lessonId : undefined,
147	    createdAt: str(material.createdAt),
148	  };
149	}
150	
151	function normalizeLesson(value: unknown): CourseLesson {
152	  const lesson = record(value);
153	  return {
154	    id: str(lesson.id),
155	    title: str(lesson.title, "Untitled lesson"),
156	    summary: str(lesson.summary),
157	    estimatedMinutes: typeof lesson.estimatedMinutes === "number" ? lesson.estimatedMinutes : undefined,
158	    objectives: strArray(lesson.objectives),
159	    reading: str(lesson.reading),
160	    materialIds: strArray(lesson.materialIds),
161	  };
162	}
163	
164	function normalizeMember(value: unknown): CourseMember {
165	  const member = record(value);
166	  const progress = record(member.progress);
167	  return {
168	    accountId: str(member.accountId),
169	    displayName: str(member.displayName, "Learner"),
170	    role: role(member.role),
171	    teacherAccess: member.teacherAccess === "full" || member.teacherAccess === "requested"
172	      ? member.teacherAccess
173	      : "private",
174	    progress: {
175	      activeLessonId: typeof progress.activeLessonId === "string" ? progress.activeLessonId : undefined,
176	      completedLessonIds: strArray(progress.completedLessonIds),
177	      lastActiveAt: str(progress.lastActiveAt),
178	    },
179	  };
180	}
181	
182	export function normalizeCourseSnapshot(value: unknown): CourseViewerSnapshot {
183	  const snapshot = record(value);
184	  const course = record(snapshot.course);
185	  const permissions = record(snapshot.permissions);
186	  return {
187	    course: {
188	      id: str(course.id),
189	      title: str(course.title, "Untitled course"),
190	      description: str(course.description),
191	      outcomes: strArray(course.outcomes),
192	      updatedAt: str(course.updatedAt),
193	      revision: typeof course.revision === "number" ? course.revision : 0,
194	      modules: (Array.isArray(course.modules) ? course.modules : []).map((module) => {
195	        const entry = record(module);
196	        return {
197	          id: str(entry.id),
198	          title: str(entry.title, "Untitled module"),
199	          description: str(entry.description),
200	          lessons: (Array.isArray(entry.lessons) ? entry.lessons : []).map(normalizeLesson),
201	        };
202	      }),
203	      materials: (Array.isArray(course.materials) ? course.materials : []).map(normalizeMaterial),
204	      members: (Array.isArray(course.members) ? course.members : []).map(normalizeMember),
205	    },
206	    viewer: normalizeMember(snapshot.viewer),
207	    permissions: {
208	      canEditCourse: permissions.canEditCourse === true,
209	      canInvite: permissions.canInvite === true,
210	      canReview: permissions.canReview === true,
211	      canEditDeck: permissions.canEditDeck === true,
212	      canRequestTeacherAccess: permissions.canRequestTeacherAccess === true,
213	    },
214	  };
215	}
216	
217	/** Lessons across every module, in course order. */
218	export function allCourseLessons(course: Pick<Course, "modules">): CourseLesson[] {
219	  return course.modules.flatMap((module) => module.lessons);
220	}

