  1	import { useRouter } from "expo-router";
  2	import { useCallback, useEffect, useRef, useState } from "react";
  3	import {
  4	  ActivityIndicator,
  5	  FlatList,
  6	  Modal,
  7	  Pressable,
  8	  RefreshControl,
  9	  StyleSheet,
 10	  Switch,
 11	  Text,
 12	  TextInput,
 13	  View,
 14	} from "react-native";
 15	import { Button } from "@/components/Buttons";
 16	import { EmptyState } from "@/components/EmptyState";
 17	import { Screen } from "@/components/Screen";
 18	import { radii, spacing, useKeatingTheme } from "@/constants/theme";
 19	import {
 20	  CourseApiError,
 21	  fetchCourses,
 22	  fetchCourseSession,
 23	  joinCourse,
 24	} from "@/lib/courses/client";
 25	import type { CourseListItem, CourseSessionAccount } from "@/lib/courses/types";
 26	
 27	export default function CoursesScreen() {
 28	  const theme = useKeatingTheme();
 29	  const styles = createStyles(theme);
 30	  const router = useRouter();
 31	  const [courses, setCourses] = useState<CourseListItem[] | null>(null);
 32	  const [account, setAccount] = useState<CourseSessionAccount | null>(null);
 33	  const [error, setError] = useState<string | null>(null);
 34	  const [refreshing, setRefreshing] = useState(false);
 35	  const [joinOpen, setJoinOpen] = useState(false);
 36	  const loadController = useRef<AbortController | null>(null);
 37	
 38	  const load = useCallback(async (mode: "initial" | "refresh") => {
 39	    loadController.current?.abort();
 40	    const controller = new AbortController();
 41	    loadController.current = controller;
 42	    if (mode === "refresh") setRefreshing(true);
 43	    setError(null);
 44	    try {
 45	      const [session, list] = await Promise.all([
 46	        fetchCourseSession({ signal: controller.signal }),
 47	        fetchCourses({ signal: controller.signal }),
 48	      ]);
 49	      if (controller.signal.aborted) return;
 50	      setAccount(session);
 51	      setCourses(list);
 52	    } catch (caught) {
 53	      if (controller.signal.aborted || (caught instanceof Error && caught.name === "AbortError")) return;
 54	      setError(caught instanceof Error ? caught.message : "Could not load your courses.");
 55	      // Keep whatever list is already on screen; a failed refresh should not
 56	      // blank out courses the learner was reading.
 57	      setCourses((current) => current ?? []);
 58	    } finally {
 59	      if (loadController.current === controller) loadController.current = null;
 60	      setRefreshing(false);
 61	    }
 62	  }, []);
 63	
 64	  useEffect(() => {
 65	    void load("initial");
 66	    return () => loadController.current?.abort();
 67	  }, [load]);
 68	
 69	  return (
 70	    <Screen
 71	      scroll={false}
 72	      title="Courses"
 73	      subtitle={account ? `Signed in as ${account.displayName}` : "Structured learning with your class or study group"}
 74	      action={<Button compact variant="secondary" onPress={() => setJoinOpen(true)}>Join</Button>}
 75	    >
 76	      {error ? (
 77	        <View style={styles.errorBanner} accessibilityRole="alert">
 78	          <Text style={styles.errorText}>{error}</Text>
 79	          <Button compact variant="quiet" onPress={() => void load("refresh")}>Try again</Button>
 80	        </View>
 81	      ) : null}
 82	
 83	      {courses === null ? (
 84	        <View style={styles.loading}>
 85	          <ActivityIndicator color={theme.colors.primaryText} />
 86	          <Text style={styles.loadingText}>Loading your courses…</Text>
 87	        </View>
 88	      ) : (
 89	        <FlatList
 90	          data={courses}
 91	          keyExtractor={(course) => course.id}
 92	          contentContainerStyle={styles.list}
 93	          refreshControl={(
 94	            <RefreshControl
 95	              refreshing={refreshing}
 96	              onRefresh={() => void load("refresh")}
 97	              tintColor={theme.colors.primaryText}
 98	            />
 99	          )}
100	          renderItem={({ item }) => (
101	            <CourseRow course={item} onPress={() => router.push(`/course/${item.id}`)} />
102	          )}
103	          ListEmptyComponent={(
104	            <EmptyState
105	              title="No courses yet"
