 33	  const load = useCallback(async () => {
 34	    if (!id) return;
 35	    controller.current?.abort();
 36	    const next = new AbortController();
 37	    controller.current = next;
 38	    setError(null);
 39	    try {
 40	      const result = await fetchCourse(id, { signal: next.signal });
 41	      if (!next.signal.aborted) setSnapshot(result);
 42	    } catch (caught) {
 43	      if (next.signal.aborted || (caught instanceof Error && caught.name === "AbortError")) return;
 44	      setError(caught instanceof Error ? caught.message : "Could not open this course.");
 45	    }
 46	  }, [id]);
 47	
 48	  useEffect(() => {
 49	    void load();
 50	    return () => controller.current?.abort();
