 60	      + `${lesson.objectives.length > 0 ? `\n\nObjectives:\n${lesson.objectives.map((o) => `- ${o}`).join("\n")}` : ""}`
 61	      + "\n\nStart by finding out what I already understand, then teach me the rest.",
 62	    );
