 79	async function withCourseLock<T>(
 80	  courseId: string,
 81	  task: () => Promise<T>,
 82	): Promise<T> {
 83	  const previous = courseLocks.get(courseId) ?? Promise.resolve();
 84	  let release!: () => void;
 85	  const gate = new Promise<void>((resolve) => {
 86	    release = resolve;
 87	  });
 88	  const tail = previous.then(() => gate);
 89	  courseLocks.set(courseId, tail);
 90	  await previous;
 91	  try {
 92	    return await task();
 93	  } finally {
 94	    release();
 95	    if (courseLocks.get(courseId) === tail) courseLocks.delete(courseId);
 96	  }
 97	}
