335	export async function joinCourseWithInvite(
336	  token: string,
337	  accountId: string,
338	  displayName: string,
339	  acceptTeacherAccess = false,
340	): Promise<CourseViewerSnapshot | null> {
341	  const tokenHash = await sha256(token);
342	  const rawInvite = await storage().getItem(`invite:${tokenHash}`);
343	  if (!rawInvite) return null;
344	  const invite = courseInviteSchema.parse(rawInvite);
345	  return withCourseLock(invite.courseId, async () => {
346	    const freshRaw = await storage().getItem(`invite:${tokenHash}`);
347	    if (!freshRaw) return null;
348	    const freshInvite = courseInviteSchema.parse(freshRaw);
349	    if (
350	      freshInvite.uses >= freshInvite.maxUses ||
351	      Date.parse(freshInvite.expiresAt) <= Date.now()
352	    )
353	      return null;
354	    const record = await loadRecord(freshInvite.courseId);
355	    if (!record) return null;
356	    const existing = record.course.members.find(
357	      (member) => member.accountId === accountId,
358	    );
359	    if (!existing) {
360	      const requiresTeacherAccess =
361	        freshInvite.role !== "teacher" &&
362	        record.course.settings.teacherAccessPolicy === "required-on-enrollment";
363	      if (requiresTeacherAccess && !acceptTeacherAccess) {
364	        throw new CourseEnrollmentConsentRequiredError();
365	      }
366	      const now = new Date().toISOString();
367	      record.course.members.push({
368	        accountId,
369	        displayName,
370	        role: freshInvite.role,
371	        teacherAccess:
372	          freshInvite.role === "teacher" || requiresTeacherAccess
373	            ? "full"
374	            : "private",
375	        joinedAt: now,
376	        progress: { completedLessonIds: [], lastActiveAt: now },
377	      });
378	      record.course.revision += 1;
379	      record.course.updatedAt = now;
380	      record.course.activity.unshift({
381	        id: freshInvite.id,
382	        type: "member-joined",
383	        accountId,
384	        message: "Joined the course",
385	        createdAt: now,
386	      });
387	      await saveRecord(record);
388	      freshInvite.uses += 1;
389	      await storage().setItem(`invite:${tokenHash}`, freshInvite);
390	      await addCourseToAccount(accountId, record.course.id);
391	    }
392	    return projectCourseForViewer(record.course, accountId);
393	  });
394	}

