  1	import type { H3Event } from "h3";
  2	import {
  3		NotOrganicFetchAdapter,
  4		type NotOrganicProductSession,
  5	} from "./fetch-adapter";
  6	
  7	export const NOTORGANIC_SESSION_ADAPTER_CONTEXT_KEY = "notOrganicSessionAdapter";
  8	export const NOTORGANIC_AUTH_OPERATIONAL_BLOCKER =
  9		"Not Organic hosted access requires a deployment-owned ATProto/Better Auth product-session adapter. Keating does not yet have durable server auth, so browser DID or email claims are intentionally rejected.";
 10	
 11	export class NotOrganicOperationalError extends Error {
 12		readonly statusCode = 503;
 13		readonly code = "notorganic_auth_adapter_unavailable";
 14	
 15		constructor(message = NOTORGANIC_AUTH_OPERATIONAL_BLOCKER) {
 16			super(message);
 17		}
 18	}
 19	
 20	export interface NotOrganicSessionRequest {
 21		feature: string;
 22	}
 23	
 24	export interface NotOrganicSessionAdapter {
 25		/**
 26		 * Resolve a product capability from a server-validated session. Implementors
 27		 * own assertion signing/exchange, refresh, revocation, and DPoP key custody.
 28		 */
 29		getProductSession(
 30			event: H3Event,
 31			request: NotOrganicSessionRequest,
 32		): Promise<NotOrganicProductSession | null>;
 33	}
 34	
 35	type NotOrganicEventContext = H3Event["context"] & {
 36		[NOTORGANIC_SESSION_ADAPTER_CONTEXT_KEY]?: NotOrganicSessionAdapter;
 37	};
 38	
 39	export function getNotOrganicSessionAdapter(event: H3Event): NotOrganicSessionAdapter {
 40		const adapter = (event.context as NotOrganicEventContext)[NOTORGANIC_SESSION_ADAPTER_CONTEXT_KEY];
 41		if (!adapter) throw new NotOrganicOperationalError();
 42		return adapter;
 43	}
 44	
 45	export async function requireNotOrganicProductSession(
 46		event: H3Event,
 47		feature: string,
 48	): Promise<NotOrganicProductSession> {
 49		const session = await getNotOrganicSessionAdapter(event).getProductSession(event, { feature });
 50		if (!session) {
 51			throw new NotOrganicOperationalError(
 52				"Sign in through the deployment-owned Keating product session before using Not Organic hosted access.",
 53			);
 54		}
 55		return session;
 56	}
 57	
 58	export interface NotOrganicServerConfig {
 59		enabled: boolean;
 60		gatewayBaseUrl: string;
 61		maxCostMicrousd: number;
 62	}
 63	
 64	function positiveIntegerEnv(name: string, env: NodeJS.ProcessEnv): number {
 65		const value = Number(env[name]);
 66		if (!Number.isSafeInteger(value) || value <= 0) {
 67			throw new NotOrganicOperationalError(`${name} must be configured as a positive integer.`);
 68		}
 69		return value;
 70	}
 71	
 72	export function isNotOrganicHostedEnabled(env: NodeJS.ProcessEnv = process.env): boolean {
 73		const value = env.NOTORGANIC_ENABLED?.trim().toLowerCase();
 74		return value === "1" || value === "true";
 75	}
 76	
 77	export function getNotOrganicServerConfig(env: NodeJS.ProcessEnv = process.env): NotOrganicServerConfig {
 78		if (!isNotOrganicHostedEnabled(env)) {
 79			return {
 80				enabled: false,
 81				gatewayBaseUrl: "",
 82				maxCostMicrousd: 0,
 83			};
 84		}
 85		const gatewayBaseUrl = env.NOTORGANIC_ISSUER?.trim().replace(/\/+$/, "");
 86		if (!gatewayBaseUrl || !gatewayBaseUrl.startsWith("https://")) {
 87			throw new NotOrganicOperationalError(
 88				"NOTORGANIC_ISSUER must be configured as an HTTPS server-only URL.",
 89			);
 90		}
 91		let gatewayUrl: URL;
 92		try {
 93			gatewayUrl = new URL(gatewayBaseUrl);
 94		} catch {
 95			throw new NotOrganicOperationalError(
 96				"NOTORGANIC_ISSUER must be a valid HTTPS gateway origin.",
 97			);
 98		}
 99		if (gatewayUrl.pathname !== "/" || gatewayUrl.search || gatewayUrl.hash) {
100			throw new NotOrganicOperationalError(
101				"NOTORGANIC_ISSUER must be the gateway origin without a /v1 path, query, or fragment.",
102			);
103		}
104		return {
105			enabled: true,
106			gatewayBaseUrl: gatewayUrl.origin,
107			maxCostMicrousd: positiveIntegerEnv("NOTORGANIC_MAX_COST_MICROUSD", env),
108		};
109	}
110	
111	export async function createNotOrganicServerClient(
112		event: H3Event,
113		feature: string,
114		config = getNotOrganicServerConfig(),
115	): Promise<NotOrganicFetchAdapter> {
116		if (!config.enabled) {
117			throw new NotOrganicOperationalError("Not Organic hosted access is disabled.");
118		}
119		return new NotOrganicFetchAdapter({
120			baseUrl: config.gatewayBaseUrl,
121			session: await requireNotOrganicProductSession(event, feature),
122		});
123	}

